function epInt(v){return Number.isInteger(v)&&v>=1&&v<=20}
function epLoad(){try{const stored=JSON.parse(localStorage.getItem(epKey)||'null');if(!stored)return;for(const t of etData){const v=stored.talents?.[t.id];if(v&&epInt(v.a)&&epInt(v.b)&&v.b>=v.a){epState[t.id].a=v.a;epState[t.id].b=v.b}}if(typeof stored.budget==='string'&&/^\d{0,12}$/.test(stored.budget))epBudget=stored.budget;if(Number.isInteger(stored.stage)&&stored.stage>=0&&stored.stage<=4)epStage=stored.stage;if(['all','attack','defense'].includes(stored.filter))epFilter=stored.filter}catch{epSaved=false}}
function epSave(){try{const talents=Object.fromEntries(Object.entries(epState).map(([id,s])=>[id,{a:s.a,b:s.b}]));localStorage.setItem(epKey,JSON.stringify({talents,budget:epBudget,stage:epStage,filter:epFilter}));epSaved=true}catch{epSaved=false}}
