function epCost(t,a,b){return t.levels[b-1].cumulative_resource_from_level_1-t.levels[a-1].cumulative_resource_from_level_1}
function epTotal(){return etData.reduce((sum,t)=>{const s=epState[t.id];return sum+epCost(t,s.a,s.b)},0)}
function epAffordable(t){const s=epState[t.id];if(epBudget==='')return s.b;const available=Number(epBudget)-(epTotal()-epCost(t,s.a,s.b));let result=s.a;for(let n=s.a;n<=20;n++){if(epCost(t,s.a,n)<=available)result=n;else break}return result}
